54: /* Set `symbol` to defaults (does not zeroize) */
55: static void set_symbol_defaults(struct zint_symbol *symbol) {
56: 
57:     symbol->symbology = BARCODE_CODE128;
58:     symbol->scale = 1.0f;
59:     memcpy(symbol->fgcolour, "000000", 7); /* Include terminating NUL */
60:     symbol->fgcolor = &symbol->fgcolour[0];
61:     memcpy(symbol->bgcolour, "ffffff", 7);
62:     symbol->bgcolor = &symbol->bgcolour[0];
63: #ifdef ZINT_NO_PNG
64:     memcpy(symbol->outfile, "out.gif", 8); /* Include terminating NUL */
65: #else
66:     memcpy(symbol->outfile, "out.png", 8);
67: #endif
68:     symbol->option_1 = -1;
69:     symbol->show_hrt = 1; /* Show human readable text */
70:     symbol->input_mode = DATA_MODE;
71:     /* symbol->eci = 0; Default 0 uses ECI 3 */
72:     symbol->dot_size = 0.8f; /* 0.4 / 0.5 */
73:     symbol->text_gap = 1.0f;
74:     symbol->guard_descent = 5.0f;
75:     symbol->warn_level = WARN_DEFAULT;
76:     symbol->bitmap = NULL;
77:     symbol->alphamap = NULL;
78:     symbol->vector = NULL;
79:     symbol->memfile = NULL;
80:     symbol->content_segs = NULL;
81: }
