83: /* Create a symbol structure and set fields to default values */
84: struct zint_symbol *ZBarcode_Create(void) {
85:     struct zint_symbol *symbol;
86: 
87:     symbol = (struct zint_symbol *) calloc(1, sizeof(*symbol)); /* Zeroizes */
88:     if (!symbol) return NULL;
89: 
90:     set_symbol_defaults(symbol);
91: 
92:     return symbol;
