97: /* Free any output buffers that may have been created and zeroize output fields */
98: void ZBarcode_Clear(struct zint_symbol *symbol) {
99:     int i;
100: 
101:     if (!symbol) return;
102: 
103:     /* Zeroize output fields */
104:     for (i = 0; i < symbol->rows; i++) {
105:         memset(symbol->encoded_data[i], 0, sizeof(symbol->encoded_data[0]));
106:     }
107:     symbol->rows = 0;
108:     symbol->width = 0;
109:     memset(symbol->row_height, 0, sizeof(symbol->row_height));
110:     memset(symbol->text, 0, sizeof(symbol->text));
111:     symbol->text_length = 0;
112:     symbol->errtxt[0] = '\0';
113: 
114:     if (symbol->bitmap != NULL) {
115:         free(symbol->bitmap);
116:         symbol->bitmap = NULL;
117:     }
118:     if (symbol->alphamap != NULL) {
119:         free(symbol->alphamap);
120:         symbol->alphamap = NULL;
121:     }
122:     symbol->bitmap_width = 0;
123:     symbol->bitmap_height = 0;
124: 
125:     if (symbol->memfile != NULL) {
126:         free(symbol->memfile);
127:         symbol->memfile = NULL;
128:     }
129:     symbol->memfile_size = 0;
130: 
131:     z_ct_free_segs(symbol);
132:     zint_vector_free(symbol);
133: }
