135: /* Free any output buffers that may have been created and reset all fields to defaults */
136: void ZBarcode_Reset(struct zint_symbol *symbol) {
137:     if (!symbol) return;
138: 
139:     if (symbol->bitmap != NULL)
140:         free(symbol->bitmap);
141:     if (symbol->alphamap != NULL)
142:         free(symbol->alphamap);
143:     if (symbol->memfile != NULL)
144:         free(symbol->memfile);
145: 
146:     z_ct_free_segs(symbol);
147:     zint_vector_free(symbol);
148: 
149:     memset(symbol, 0, sizeof(*symbol));
150:     set_symbol_defaults(symbol);
151: }
