248: /* Helper to convert `error_number` based on `warn_level` */
249: static int error_warn_level(int error_number, struct zint_symbol *symbol) {
250:     if (error_number < ZINT_ERROR && (symbol->warn_level & 0xFF) == WARN_FAIL_ALL) {
251:         /* Convert to error equivalent */
252:         if (error_number == ZINT_WARN_NONCOMPLIANT) {
253:             error_number = ZINT_ERROR_NONCOMPLIANT;
254:         } else if (error_number == ZINT_WARN_USES_ECI) {
255:             error_number = ZINT_ERROR_USES_ECI;
256:         } else if (error_number == ZINT_WARN_INVALID_OPTION) {
257:             error_number = ZINT_ERROR_INVALID_OPTION;
258:         } else if (error_number == ZINT_WARN_HRT_TRUNCATED) {
259:             error_number = ZINT_ERROR_HRT_TRUNCATED;
260:         } else { /* Shouldn't happen */
261:             assert(0); /* Not reached */
262:             error_number = ZINT_ERROR_ENCODING_PROBLEM;
263:         }
264:     }
265:     return error_number;
266: }
