268: /* Prefix error message with Error/Warning */
269: static int error_tag(int error_number, struct zint_symbol *symbol, const int err_id, const char *error_string) {
270: 
271:     if (error_number != 0) {
272:         if (error_string) {
273:             z_errtxt(0, symbol, err_id, error_string);
274:         }
275:         error_number = error_warn_level(error_number, symbol);
276:         if (error_number >= ZINT_ERROR) {
277:             z_errtxt_adj(0, symbol, "Error %s", NULL);
278:         } else {
279:             z_errtxt_adj(0, symbol, "Warning %s", NULL);
280:         }
281:     }
282: 
283:     return error_number;
284: }
