430: /* Process health industry bar code data */
431: static int hibc(struct zint_symbol *symbol, struct zint_seg segs[], const int seg_count) {
432:     /* Permitted HIBC characters */
433:     static const char TECHNETIUM[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ-. $/+%"; /* Same as SILVER (CODE39) */
434:     unsigned char *source = segs[0].source;
435:     int length = segs[0].length;
436: 
437:     int i;
438:     int counter, error_number = 0;
439:     char to_process[110 + 2 + 1];
440:     int posns[110];
441: 
442:     const int content_segs = symbol->output_options & BARCODE_CONTENT_SEGS;
443: 
444:     /* Without "+" and check: max 110 characters in HIBC 2.6 */
445:     if (length > 110) {
446:         return z_errtxtf(ZINT_ERROR_TOO_LONG, symbol, 202, "Input length %d too long for HIBC LIC (maximum 110)",
447:                         length);
448:     }
449:     z_to_upper(source, length);
450:     if ((i = z_not_sane_lookup(TECHNETIUM, sizeof(TECHNETIUM) - 1, source, length, posns))) {
451:         return z_errtxtf(ZINT_ERROR_INVALID_DATA, symbol, 203,
452:                         "Invalid character at position %d in input (alphanumerics, space and \"-.$/+%%\" only)", i);
453:     }
454: 
455:     counter = 41;
456:     for (i = 0; i < length; i++) {
457:         counter += posns[i];
458:     }
459:     counter = counter % 43;
460: 
461:     to_process[0] = '+';
462:     memcpy(to_process + 1, source, length);
463:     to_process[++length] = TECHNETIUM[counter];
464:     to_process[++length] = '\0';
465: 
466:     segs[0].source = (unsigned char *) to_process;
467:     segs[0].length = length;
468:     assert(seg_count == 1);
469: 
470:     if (symbol->debug & ZINT_DEBUG_PRINT) printf("HIBC processed source: %s\n", to_process);
471: 
472:     /* Code 128, Code 39 & Codablock F set `content_segs` themselves, but the others don't, so do it now */
473:     assert(!symbol->content_segs); /* HIBC symbologies don't satisfy `supports_non_iso8859_1()` */
474:     if (content_segs && symbol->symbology != BARCODE_HIBC_128 && symbol->symbology != BARCODE_HIBC_39
475:                     && symbol->symbology != BARCODE_HIBC_BLOCKF) {
476:         if (z_ct_cpy_segs(symbol, segs, seg_count)) {
477:             return error_tag(ZINT_ERROR_MEMORY, symbol, -1, NULL); /* `z_ct_cpy_segs()` only fails with OOM */
478:         }
479:     }
480: 
481:     switch (symbol->symbology) {
482:         case BARCODE_HIBC_128:
483:             error_number = zint_code128(symbol, segs[0].source, segs[0].length);
484:             z_hrt_cpy_chr(symbol, '*');
485:             z_hrt_cat_nochk(symbol, segs[0].source, segs[0].length);
486:             z_hrt_cat_chr_nochk(symbol, '*');
487:             break;
488:         case BARCODE_HIBC_39:
489:             symbol->option_2 = 0;
490:             error_number = zint_code39(symbol, segs[0].source, segs[0].length);
491:             z_hrt_cpy_chr(symbol, '*');
492:             z_hrt_cat_nochk(symbol, segs[0].source, segs[0].length);
493:             z_hrt_cat_chr_nochk(symbol, '*');
494:             break;
495:         case BARCODE_HIBC_DM:
496:             error_number = zint_datamatrix(symbol, segs, seg_count);
497:             break;
498:         case BARCODE_HIBC_QR:
499:             error_number = zint_qrcode(symbol, segs, seg_count);
500:             break;
501:         case BARCODE_HIBC_PDF:
502:             error_number = zint_pdf417(symbol, segs, seg_count);
503:             break;
504:         case BARCODE_HIBC_MICPDF:
505:             error_number = zint_micropdf417(symbol, segs, seg_count);
506:             break;
507:         case BARCODE_HIBC_AZTEC:
