581: static int reduced_charset(struct zint_symbol *symbol, struct zint_seg segs[], const int seg_count);
582: 
583: /* Main dispatch, checking for barcodes which handle ECIs/character sets themselves, otherwise calling
584:    `reduced_charset()` */
585: static int extended_or_reduced_charset(struct zint_symbol *symbol, struct zint_seg segs[], const int seg_count) {
586:     int error_number = 0;
587: 
588:     switch (symbol->symbology) {
589:         /* These are the "elite" standards which have support for specific character sets + ECI */
590:         case BARCODE_QRCODE:
591:         case BARCODE_GRIDMATRIX:
592:         case BARCODE_HANXIN:
593:         case BARCODE_RMQR:
594:             error_number = barcode_seg_funcs[symbol->symbology - LIB_SEG_FUNCS_START](symbol, segs, seg_count);
595:             break;
596:         /* These are the standards which have support for specific character sets but not ECI */
597:         case BARCODE_MICROQR:
598:         case BARCODE_UPNQR:
599:             error_number = barcode_src_funcs[symbol->symbology](symbol, segs[0].source, segs[0].length);
600:             break;
601:         default: error_number = reduced_charset(symbol, segs, seg_count);
602:             break;
603:     }
604: 
605:     return error_number;
606: }
607: 
608: /* These are the "norm" standards which only support Latin-1 at most, though a few support ECI */
609: static int reduced_charset(struct zint_symbol *symbol, struct zint_seg segs[], const int seg_count) {
610:     int error_number = 0;
611:     int i;
612:     struct zint_seg *local_segs = (struct zint_seg *) z_alloca(sizeof(struct zint_seg) * seg_count);
613:     int *convertible = (int *) z_alloca(sizeof(int) * seg_count);
614: 
615:     if ((symbol->input_mode & 0x07) == UNICODE_MODE && zint_is_eci_convertible_segs(segs, seg_count, convertible)) {
616:         unsigned char *preprocessed;
617:         const int eci_length_segs = zint_get_eci_length_segs(segs, seg_count);
618:         unsigned char *preprocessed_buf = (unsigned char *) z_alloca(eci_length_segs + seg_count);
619: 
620:         /* Prior check ensures ECI only set for those that support it */
621:         z_segs_cpy(symbol, segs, seg_count, local_segs); /* Shallow copy (needed to set default ECIs) */
622:         preprocessed = preprocessed_buf;
623:         for (i = 0; i < seg_count; i++) {
624:             if (convertible[i]) {
625:                 error_number = zint_utf8_to_eci(local_segs[i].eci, local_segs[i].source, preprocessed,
626:                                             &local_segs[i].length);
627:                 if (error_number != 0) {
628:                     if (local_segs[i].eci) {
629:                         return z_errtxtf(error_number, symbol, 244, "Invalid character in input for ECI '%d'",
630:                                         local_segs[i].eci);
631:                     }
632:                     return z_errtxt(error_number, symbol, 204, "Invalid character in input (ISO/IEC 8859-1 only)");
633:                 }
634:                 local_segs[i].source = preprocessed;
635:                 preprocessed += local_segs[i].length + 1;
636:             }
637:         }
638:         if (barcode_src_funcs[symbol->symbology]) {
639:             error_number = barcode_src_funcs[symbol->symbology](symbol, local_segs[0].source, local_segs[0].length);
640:         } else {
641:             assert(symbol->symbology >= LIB_SEG_FUNCS_START); /* Suppress clang-tidy-20 warning */
642:             assert(barcode_seg_funcs[symbol->symbology - LIB_SEG_FUNCS_START]); /* Suppress clang-tidy-20 warning */
643:             error_number = barcode_seg_funcs[symbol->symbology - LIB_SEG_FUNCS_START](symbol, local_segs, seg_count);
644:         }
645:     } else {
646:         if (barcode_src_funcs[symbol->symbology]) {
647:             error_number = barcode_src_funcs[symbol->symbology](symbol, segs[0].source, segs[0].length);
648:         } else {
649:             assert(symbol->symbology >= LIB_SEG_FUNCS_START); /* Suppress clang-tidy-19 warning */
650:             assert(barcode_seg_funcs[symbol->symbology - LIB_SEG_FUNCS_START]); /* Suppress clang-tidy-19 warning */
651:             z_segs_cpy(symbol, segs, seg_count, local_segs); /* Shallow copy (needed to set default ECIs) */
652:             error_number = barcode_seg_funcs[symbol->symbology - LIB_SEG_FUNCS_START](symbol, local_segs, seg_count);
653:         }
654:     }
655: 
656:     return error_number;
657: }
