659: /* Remove Unicode BOM at start of data */
660: static void strip_bom(unsigned char *source, int *input_length) {
661:     int i;
662: 
663:     /* Note if BOM is only data then not stripped */
664:     if (*input_length > 3 && source[0] == 0xEF && source[1] == 0xBB && source[2] == 0xBF) {
665:         /* BOM at start of input data, strip in accordance with RFC 3629 */
666:         for (i = 3; i <= *input_length; i++) { /* Include terminating NUL */
667:             source[i - 3] = source[i];
668:         }
669:         *input_length -= 3;
670:     }
671: }
