679: /* Helper to convert base octal, decimal, hexadecimal escape sequence */
680: static int esc_base(struct zint_symbol *symbol, const unsigned char *input_string, const int length,
681:             const int in_posn, const unsigned char base) {
682:     int c1, c2, c3;
683:     int min_len = base == 'x' ? 2 : 3;
684:     int val = -1;
685: 
686:     if (in_posn + min_len > length) {
687:         return z_errtxtf(-1, symbol, 232, "Incomplete '\\%c' escape sequence in input", base);
688:     }
689:     c1 = z_ctoi(input_string[in_posn]);
690:     c2 = z_ctoi(input_string[in_posn + 1]);
691:     if (base == 'd') {
692:         c3 = z_ctoi(input_string[in_posn + 2]);
693:         if ((c1 >= 0 && c1 <= 9) && (c2 >= 0 && c2 <= 9) && (c3 >= 0 && c3 <= 9)) {
694:             val = c1 * 100 + c2 * 10 + c3;
695:         }
696:     } else if (base == 'o') {
697:         c3 = z_ctoi(input_string[in_posn + 2]);
698:         if ((c1 >= 0 && c1 <= 7) && (c2 >= 0 && c2 <= 7) && (c3 >= 0 && c3 <= 7)) {
699:             val = (c1 << 6) | (c2 << 3) | c3;
700:         }
701:     } else {
702:         if (c1 >= 0 && c2 >= 0) {
703:             val = (c1 << 4) | c2;
704:         }
705:     }
706: 
707:     if (val == -1) {
708:         return ZEXT z_errtxtf(-1, symbol, 238,
709:                                 "Invalid character in escape sequence '%2$.*1$s' in input (%3$s only)",
710:                                 base == 'x' ? 4 : 5, input_string + in_posn - 2,
711:                                 base == 'd' ? "decimal" : base == 'o' ? "octal" : "hexadecimal");
712:     }
713:     if (val > 255) {
714:         assert(base != 'x');
715:         return ZEXT z_errtxtf(-1, symbol, 237,
716:                                 "Value of escape sequence '%1$.5s' in input out of range (000 to %2$s)",
717:                                 input_string + in_posn - 2, base == 'd' ? "255" : "377");
718:     }
719: 
720:     return val;
721: }
