723: /* Helper to parse escape sequences. If `escaped_string` NULL, calculates length only */
724: static int escape_char_process(struct zint_symbol *symbol, const unsigned char *input_string, int *p_length,
725:             unsigned char *escaped_string) {
726:     /* NOTE: if add escape character, must also update regex `escRE` in "frontend_qt/datawindow.php" */
727:     static const char escs[] = {
728:       /* NUL   EOT   BEL   BS    HT    LF    VT    FF    CR    DLE   ESC   FS    GS    RS   US   \ */
729:          '0',  'E',  'a',  'b',  't',  'n',  'v',  'f',  'r',  'L',  'e',  'F',  'G',  'R', 'N', '\\', '\0'
730:     };
731:     static const char vals[] = {
732:         0x00, 0x04, 0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x10, 0x1B, 0x1C, 0x1D, 0x1E, 0x1F, 0x5C
733:     };
734:     const int length = *p_length;
735:     int in_posn = 0, out_posn = 0;
736:     unsigned char ch;
737:     int val, esc_posn;
738:     int i;
739:     unsigned int unicode;
740:     const int extra_escape_mode = symbol->input_mode & EXTRA_ESCAPE_MODE;
741:     const int can_extra_escape = supports_extra_escape_mode(symbol);
742:     const int escape_parens = (symbol->input_mode & GS1PARENS_MODE)
743:                                 && ((symbol->input_mode & 0x07) == GS1_MODE || check_force_gs1(symbol->symbology));
744: 
745:     do {
746:         if (input_string[in_posn] == '\\') {
747:             if (in_posn + 1 >= length) {
748:                 return z_errtxt(ZINT_ERROR_INVALID_DATA, symbol, 236, "Incomplete escape character in input");
749:             }
750:             ch = input_string[in_posn + 1];
751:             if ((esc_posn = z_posn(escs, ch)) != -1) {
752:                 if (escaped_string) escaped_string[out_posn] = vals[esc_posn];
753:                 in_posn += 2;
754:                 /* Note: if given double backslash following by caret "\\^" then will be passed through as "\^",
755:                    i.e. the start of an extra escape sequence, avoiding the check below, so each symbology needs
756:                    to also check themselves */
757:             } else {
758:                 switch (ch) {
759:                     case '^': /* Symbology specific */
760:                         if (!extra_escape_mode || !can_extra_escape) {
761:                             if (!extra_escape_mode) {
762:                                 return z_errtxt(ZINT_ERROR_INVALID_DATA, symbol, 798,
763:                                                 "Escape '\\^' only valid in Extra Escape mode");
764:                             }
765:                             return z_errtxt(ZINT_ERROR_INVALID_DATA, symbol, 213,
766:                                             "Extra escape '\\^' not valid for this symbology and/or input mode");
767:                         }
768:                         /* Pass thru unaltered */
769:                         if (escaped_string) {
770:                             escaped_string[out_posn++] = '\\';
771:                             escaped_string[out_posn] = '^';
772:                         } else {
773:                             out_posn++;
774:                         }
775:                         in_posn += 2;
776:                         if (in_posn < length) { /* Note allowing '\\^' on its own at end */
777:                             if (escaped_string) {
778:                                 escaped_string[++out_posn] = input_string[in_posn++];
779:                             } else {
780:                                 ++out_posn;
781:                                 in_posn++;
782:                             }
783:                         }
784:                         break;
785:                     case '(':
786:                     case ')':
787:                         if (!escape_parens) {
788:                             return z_errtxt(ZINT_ERROR_INVALID_DATA, symbol, 853,
789:                                             "Escaped parentheses only valid in GS1 mode with GS1 parentheses flag");
790:                         }
791:                         /* Pass through unaltered */
792:                         if (escaped_string) {
793:                             escaped_string[out_posn++] = '\\';
794:                             escaped_string[out_posn] = ch;
795:                         } else {
796:                             out_posn++;
797:                         }
798:                         in_posn += 2;
799:                         break;
800:                     case 'd':
801:                     case 'o':
802:                     case 'x':
803:                         if ((val = esc_base(symbol, input_string, length, in_posn + 2, ch)) == -1) {
804:                             return ZINT_ERROR_INVALID_DATA;
805:                         }
806:                         if (escaped_string) escaped_string[out_posn] = val;
807:                         in_posn += 4 + (ch != 'x');
808:                         break;
809:                     case 'u':
810:                     case 'U':
811:                         if (in_posn + 6 > length || (ch == 'U' && in_posn + 8 > length)) {
812:                             return z_errtxtf(ZINT_ERROR_INVALID_DATA, symbol, 209,
813:                                             "Incomplete '\\%c' escape sequence in input", ch);
814:                         }
815:                         unicode = 0;
816:                         for (i = 0; i < 6; i++) {
817:                             if ((val = z_ctoi(input_string[in_posn + i + 2])) == -1) {
818:                                 return z_errtxtf(ZINT_ERROR_INVALID_DATA, symbol, 211,
819:                                         "Invalid character for '\\%c' escape sequence in input (hexadecimal only)",
820:                                         ch);
821:                             }
822:                             unicode = (unicode << 4) | val;
823:                             if (i == 3 && ch == 'u') {
824:                                 break;
825:                             }
826:                         }
827:                         /* Exclude reversed BOM and surrogates and out-of-range */
828:                         if (unicode == 0xFFFE || (unicode >= 0xD800 && unicode < 0xE000) || unicode > 0x10FFFF) {
829:                             return z_errtxtf(ZINT_ERROR_INVALID_DATA, symbol, 216,
830:                                             "Value of escape sequence '%.*s' in input out of range",
831:                                             ch == 'u' ? 6 : 8, input_string + in_posn);
832:                         }
833:                         if (unicode < 0x80) {
834:                             if (escaped_string) escaped_string[out_posn] = (unsigned char) unicode;
835:                         } else if (unicode < 0x800) {
836:                             if (escaped_string) {
837:                                 escaped_string[out_posn++] = (unsigned char) (0xC0 | (unicode >> 6));
838:                                 escaped_string[out_posn] = (unsigned char) (0x80 | (unicode & 0x3F));
839:                             } else {
840:                                 out_posn++;
841:                             }
842:                         } else if (unicode < 0x10000) {
843:                             if (escaped_string) {
844:                                 escaped_string[out_posn++] = (unsigned char) (0xE0 | (unicode >> 12));
845:                                 escaped_string[out_posn++] = (unsigned char) (0x80 | ((unicode >> 6) & 0x3F));
846:                                 escaped_string[out_posn] = (unsigned char) (0x80 | (unicode & 0x3F));
847:                             } else {
848:                                 out_posn += 2;
849:                             }
850:                         } else {
851:                             if (escaped_string) {
852:                                 escaped_string[out_posn++] = (unsigned char) (0xF0 | (unicode >> 18));
853:                                 escaped_string[out_posn++] = (unsigned char) (0x80 | ((unicode >> 12) & 0x3F));
854:                                 escaped_string[out_posn++] = (unsigned char) (0x80 | ((unicode >> 6) & 0x3F));
855:                                 escaped_string[out_posn] = (unsigned char) (0x80 | (unicode & 0x3F));
856:                             } else {
857:                                 out_posn += 3;
858:                             }
859:                         }
860:                         in_posn += 6 + (ch == 'U') * 2;
861:                         break;
862:                     default:
863:                         return z_errtxtf(ZINT_ERROR_INVALID_DATA, symbol, 234,
864:                                         "Unrecognised escape character '\\%c' in input",
865:                                         !z_isascii(ch) || z_iscntrl(ch) ? '?' : ch);
866:                         break;
867:                 }
868:             }
869:         } else {
870:             if (escaped_string) escaped_string[out_posn] = input_string[in_posn];
871:             in_posn++;
872:         }
873:         out_posn++;
874:     } while (in_posn < length);
875: 
876:     if (escaped_string) {
877:         escaped_string[out_posn] = '\0';
878:     }
879:     *p_length = out_posn;
880: 
881:     return 0;
882: }
